Scanner input = new Scanner(System.in);
double[] scores = new double[6];
// Read student scores
for (int i = 0; i < scores.length; i++) {
scores[i] = input.nextDouble();
}
double total = 0;
// Add all scores
for (double score : scores) {
total += score;
}
double average = total / scores.length;
System.out.println(average);
input.close();
}
}

